            aOrbiterD = (((aWandererB + RotL64(aScatter, 39U)) + RotL64(aCarry, 11U)) + 0xD9D7BB55215F7A25ULL) + aOASaltA[(((511U - aIndex) + 137U)) & S_SALT1];
            aOrbiterE = (((aWandererK + RotL64(aCross, 47U)) + RotL64(aCarry, 3U)) + 0xBB745E257F38C2D3ULL) + aOASaltF[((aIndex + 431U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x4D5379D085DDB779ULL) + aOUSaltG[(((511U - aIndex) + 374U)) & S_SALT1];
