            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0xD9C49BA43C6EAD46ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x771212AB0351B57CULL;
            aOrbiterF = RotL64((aOrbiterF * 0x09742C7CD8C624A5ULL), 35U);
