            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xC5A1E47B083CA8C5ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xE3D4C540B3D02521ULL;
