            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x2248A0D7C409C853ULL) + aOUSaltB[(((511U - aIndex) + 276U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x16AA47A8A7EE6942ULL;
