            aWandererI = aWandererI + (((RotL64(aIngress, 58U) + aOrbiterA) + RotL64(aOrbiterH, 27U)) + RotL64(aCarry, 41U));
            aWandererH = aWandererH ^ ((RotL64(aCross, 37U) + aOrbiterF) + RotL64(aOrbiterC, 3U));
            aWandererD = aWandererD + ((((RotL64(aPrevious, 47U) + aOrbiterE) + RotL64(aOrbiterA, 35U)) + RotL64(aCarry, 11U)) + aWUSaltE[((aIndex + 155U)) & S_SALT1]);
