            aOrbiterK = (((aWandererJ + RotL64(aPrevious, 41U)) + RotL64(aCarry, 47U)) + 0x8A7973A36A65DC7CULL) + aOASaltH[((aIndex + 337U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aCross, 47U)) + RotL64(aCarry, 21U)) + 0xADDF4BDAC780F26EULL;
            aOrbiterA = ((aWandererG + RotL64(aIngress, 29U)) + 0x61351472B473C3DFULL) + aOASaltB[(((511U - aIndex) + 250U)) & S_SALT1];
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 35U)) + 0xB6EB7E0234087424ULL) + aOASaltA[((aIndex + 326U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aScatter, 54U)) + RotL64(aCarry, 3U)) + 0x321B2065BAEAC28BULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0xC96850FCB7AB13FAULL) + aOUSaltB[(((511U - aIndex) + 150U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x2EA0FE38BE8CB822ULL) ^ aOUSaltG[((aIndex + 191U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x07ACC358D9BD9D39ULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xA785984F84A765FBULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x27B12DC50FDEEA1DULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEDCADC92C4CD7157ULL), 53U);
            //
