            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xDB880CF1CBF68CB6ULL) + aOUSaltE[((aIndex + 279U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xB4D354911DEC46D5ULL) ^ aOUSaltH[((aIndex + 204U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x7791EF75545F5997ULL), 13U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0x59680A2B384D4F32ULL) + aOUSaltD[(((511U - aIndex) + 313U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0xCB9160891DD82D58ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2C711914457E20F9ULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x3A4C1831280CBB4AULL;
