            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x6F50DB6B755F19DDULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x548C8E41E6D07570ULL) ^ aOUSaltD[(((511U - aIndex) + 73U)) & S_SALT1];
