            //
            aOrbiterC = ((aOrbiterC + aOrbiterA) + 0xA85DC27E40B779ADULL) + aOUSaltB[((aIndex + 300U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x4992E9758D4B3997ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2DEEE0453CA63EE5ULL), 57U);
