            aOrbiterC = (aWandererH + RotL64(aCross, 10U)) + 0x11D4F6D7B860CF2FULL;
            aOrbiterB = ((aWandererD + RotL64(aIngress, 19U)) + 0x5C5C49BC5350E6A0ULL) + aOASaltF[(((511U - aIndex) + 317U)) & S_SALT1];
