            aOrbiterH = (aWandererD + RotL64(aCross, 29U)) + 0x8E92A697A026EE6EULL;
            aOrbiterJ = ((aWandererF + RotL64(aScatter, 23U)) + RotL64(aCarry, 41U)) + 0x0457D66C16520327ULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 53U)) + 0xF53CCB22254533D9ULL;
            aOrbiterE = ((aWandererG + RotL64(aPrevious, 43U)) + 0x38D96B0A372C32DDULL) + aOASaltE[(((511U - aIndex) + 397U)) & S_SALT1];
            aOrbiterG = ((aWandererI + RotL64(aScatter, 4U)) + 0xBE41A8DAE1612D50ULL) + aOASaltD[((aIndex + 176U)) & S_SALT1];
            aOrbiterA = (aWandererE + RotL64(aIngress, 11U)) + 0x102DB9FC568B89A9ULL;
            aOrbiterC = (((aWandererH + RotL64(aCross, 57U)) + RotL64(aCarry, 11U)) + 0xD65EFC6D26C58A0BULL) + aOASaltG[((aIndex + 333U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x4E31CED5E937EADAULL) + aOUSaltH[(((511U - aIndex) + 154U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x240B7631B121F011ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x04EFC44599B4E3E9ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xF05DF16F61F2B3F9ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x2665DA5F42EEFA18ULL) ^ aOUSaltF[((aIndex + 432U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x1A56BC180DD613CFULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x6F69CCA6E5565060ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x2701CCD8F29E7D51ULL;
