            aOrbiterA = (((aWandererH + RotL64(aPrevious, 39U)) + RotL64(aCarry, 57U)) + 0x85B3C3F3D26C1418ULL) + aOASaltC[(((511U - aIndex) + 114U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aIngress, 20U)) + 0xC6AECCD2C23F53E5ULL;
